const root=document.querySelector('#indiretos-view');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const categories=['Todos','Escritório','Limpeza','Cozinha','EPIs','Uniformes'];
let rows=[],history=[],category='Todos',tab='MRP',search='',selectedCode='';
const routeTabs={'insumos-mrp':'MRP','insumos-estoque':'Estoque','insumos-prazos':'Prazos','insumos-importacoes':'Importações',indiretos:'MRP'};
function syncIndirectNav(){const key=location.hash.slice(1),active=Object.hasOwn(routeTabs,key),children=document.querySelector('#nav-indirect-children'),parent=document.querySelector('#nav-indirect-toggle');if(!children||!parent)return;children.hidden=!active;parent.setAttribute('aria-expanded',String(active));parent.classList.toggle('indirect-active',active);document.querySelectorAll('[data-indirect-tab]').forEach(a=>{if(a.dataset.indirectTab===routeTabs[key])a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(active)tab=routeTabs[key];}

const num=s=>{let t=String(s??'').trim().replace(/\s/g,'');if(t.includes(','))t=t.replace(/\./g,'').replace(',','.');return Number(t)||0};
const iso=s=>{const m=String(s||'').match(/^(\d{2})\/(\d{2})\/(\d{4})/);return m?m[3]+'-'+m[2]+'-'+m[1]:''};
const br=s=>s?s.slice(8,10)+'/'+s.slice(5,7)+'/'+s.slice(0,4):'—';
function classify(name,group){let s=name.toUpperCase();if(group==='epis')return /CAMISETA|CALCA|CALÇA|UNIFORME|JALECO/.test(s)?'Uniformes':'EPIs';if(/PAPEL TOALHA|VASSOUR|ESPONJA|DETERGENTE|DESINFET|SABAO|SABÃO|LIMPEZA|ESCOVA|AROMATIZ/.test(s))return 'Limpeza';if(/COPO|CAFÉ|CAFE|FILTRO DE PAPEL|GUARDANAPO|COZINHA/.test(s))return 'Cozinha';return 'Escritório'}
function parseCSV(text,group){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(s=>s.trim());const split=line=>{let out=[],v='',q=false;for(let i=0;i<line.length;i++){let c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){v+='"';i++}else q=!q}else if(c===';'&&!q){out.push(v.trim());v=''}else v+=c}out.push(v.trim());return out};const headers=split(lines.shift()).map(s=>s.toLowerCase().replace(/\s+/g,' ').trim());const get=(cols,name)=>cols[headers.indexOf(name)]||'';if(!headers.includes('cód. item')||!headers.includes('dt. entrega')||!headers.includes('quantidade'))throw Error('CSV incompatível: verifique as colunas Cód. Item, Dt. Entrega e Quantidade.');return lines.map(line=>{const c=split(line),code=get(c,'cód. item'),order=get(c,'ordem'),delivery=iso(get(c,'dt. entrega')),description=get(c,'descrição');return {id:[order,code,delivery].join('|'),code,order,description,quantity:num(get(c,'quantidade')),unit:get(c,'um'),purchase:iso(get(c,'dt. compra')),delivery,company:get(c,'emp.'),type:get(c,'tipo'),category:classify(description,group),status:'Pendente',stock:null,safety:null,consumption:null,lead:null}}).filter(x=>x.code)}
async function load(){try{const r=await fetch('/api/indirect-materials',{cache:'no-store'});if(!r.ok)throw Error('Não foi possível carregar os materiais.');const j=await r.json();rows=j.items||[];history=j.history||[];render()}catch(e){root.innerHTML='<section class="panel"><h3>Materiais Indiretos</h3><p>'+esc(e.message)+'</p></section>'}}
async function save(){const r=await fetch('/api/indirect-materials',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:rows,history})});const j=await r.json();if(!r.ok)throw Error(j.error||'Falha ao salvar.')}
const today=()=>new Date().toLocaleDateString('en-CA');
function filtered(){return rows.filter(x=>(category==='Todos'||x.category===category)&&(!search||[x.code,x.description,x.order].join(' ').toLowerCase().includes(search.toLowerCase())))}
function status(x){return x.status==='Recebido'?'Recebido':x.status==='Cancelado'?'Cancelado':x.delivery&&x.delivery<today()?'Atrasado':x.status||'Pendente'}

function deadlineView(){
 const statuses=['Aguardando entrega','Parcial','Entregue','Cancelado','Atrasado'];
 const state=x=>x.status==='Recebido'?'Entregue':x.status==='Cancelado'?'Cancelado':num(x.delivered)>0?'Parcial':status(x)==='Atrasado'?'Atrasado':'Aguardando entrega';
 const now=today(),week=new Date(now+'T12:00:00'),next=new Date(week);next.setDate(next.getDate()+7);const horizon=next.toISOString().slice(0,10);
 const count=k=>rows.filter(x=>state(x)===k).length;
 const suppliers=[...new Set(rows.map(x=>x.supplier||'').filter(Boolean))].sort();
 const options=items=>items.map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('');
 const sel=(attr,values,all='Todos')=>'<select '+attr+'><option value="">'+all+'</option>'+options(values)+'</select>';
 const start=root.dataset.from||'',end=root.dataset.to||'',supplier=root.dataset.indSupplier||'',st=root.dataset.indStatus||'',q=root.dataset.indQuery||'';
 const matches=x=>(!supplier||String(x.supplier||'').toLowerCase().includes(supplier.toLowerCase()))&&(!st||state(x)===st)&&(!q||[x.code,x.description,x.order].join(' ').toLowerCase().includes(q.toLowerCase()))&&(!start||x.delivery>=start)&&(!end||x.delivery<=end);
 const shown=rows.filter(matches).sort((a,b)=>a.delivery.localeCompare(b.delivery));
 const rowsHtml=shown.map(x=>{const stx=state(x),left=Math.max(0,x.quantity-num(x.delivered));return '<tr class="'+(stx==='Atrasado'?'ind-late':stx==='Entregue'?'ind-done':'')+'"><td>'+esc(x.code)+'</td><td>'+esc(x.description)+'</td><td>'+esc(x.order)+'</td><td>'+esc(x.contact||'—')+'</td><td>'+esc(x.supplier||'—')+'</td><td>'+stx+'</td><td>'+br(x.delivery)+'</td><td>'+x.quantity+'</td><td>'+num(x.delivered)+'</td><td>'+left+'</td><td>'+esc(x.unit)+'</td><td class="ind-actions"><button data-partial="'+esc(x.id)+'" title="Entrega parcial">½</button><button data-receive="'+esc(x.id)+'" title="Receber tudo">✓</button><button data-cancel="'+esc(x.id)+'" title="Cancelar pedido">×</button></td></tr>'}).join('');
 return '<div class="deadline-kpis">'+[['Atrasados',count('Atrasado')],['Próxima semana',rows.filter(x=>!['Recebido','Cancelado'].includes(x.status)&&x.delivery>=now&&x.delivery<=horizon).length],['Pendentes',rows.filter(x=>!['Recebido','Cancelado'].includes(x.status)).length],['Parciais',count('Parcial')],['Entregues',count('Entregue')]].map(([label,value])=>'<div><strong>'+value+'</strong><span>'+label+'</span></div>').join('')+'</div>'+
 '<section class="panel deadline-purchase-entry"><details><summary>+ Adicionar pedido comprado</summary><form id="ind-purchase-form"><div class="ind-order-fields"><label>Pedido de compra<input name="order" required></label><label>Código do item<input name="code" required></label><label>Descrição<input name="description" required></label><label>Quantidade<input name="quantity" type="number" min="0.001" step="any" required></label><label>UN<input name="unit" value="UN" required></label><label>Fornecedor<input name="supplier"></label><label>Contato<input name="contact"></label><label>Entrega prevista<input name="delivery" type="date" required></label></div><button type="submit">Salvar pedido comprado</button></form></details></section>'+
 '<section class="panel deadline-report"><h3>📊 Relatório <small>Filtre antes de imprimir ou baixar</small></h3><div class="deadline-report-filters"><label>Empresa'+sel('data-ind-report-company',['Colafix'])+'</label><label>Fornecedor'+sel('data-ind-report-supplier',suppliers)+'</label><label>Status'+sel('data-ind-report-status',statuses)+'</label><label>Data inicial<input type="date" data-from value="'+start+'"></label><label>Data final<input type="date" data-to value="'+end+'"></label></div><div class="deadline-report-footer"><span>'+shown.length+' registros</span><div><button type="button" data-ind-print>🖨 Imprimir relatório</button><button type="button" data-ind-excel>📊 Baixar Excel</button></div></div></section>'+
 '<section class="panel"><h3>Controle dos prazos</h3><p class="hint">Branco: prazo normal · Vermelho: atrasado · Verde: entregue. Entrega parcial continua pendente até o saldo ser recebido.</p><div class="cement-filters"><label>Fornecedor<input data-ind-supplier placeholder="Todos" value="'+esc(supplier)+'"></label><label>Status'+sel('data-ind-status',statuses)+'</label><label>Buscar<input data-ind-query placeholder="Código, produto ou pedido" value="'+esc(q)+'"></label></div><div class="table-scroll"><table class="deadlines-grid"><thead><tr>'+['Cód','Produto','Pedido','Contato','Fornecedor','Status','Entrega prevista','Pedido','Entregue','Saldo','UN','Ações'].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+(rowsHtml||'<tr><td colspan="12">Nenhum pedido encontrado.</td></tr>')+'</tbody></table></div></section>';
}
function wireDeadlines(){
 const st=x=>x.status==='Recebido'?'Entregue':x.status==='Cancelado'?'Cancelado':num(x.delivered)>0?'Parcial':status(x)==='Atrasado'?'Atrasado':'Aguardando entrega';
 for(const [attr,key] of [['data-ind-supplier','indSupplier'],['data-ind-status','indStatus'],['data-ind-query','indQuery'],['data-from','from'],['data-to','to']]){const el=root.querySelector('['+attr+']');if(el){el.value=root.dataset[key]||'';el.onchange=()=>{root.dataset[key]=el.value;render()}}}
 for(const [attr,key] of [['data-ind-report-supplier','indSupplier'],['data-ind-report-status','indStatus']]){const el=root.querySelector('['+attr+']');if(el){el.value=root.dataset[key]||'';el.onchange=()=>{root.dataset[key]=el.value;render()}}}
 const form=root.querySelector('#ind-purchase-form');if(form)form.onsubmit=async e=>{e.preventDefault();const d=new FormData(form),code=String(d.get('code')).trim(),order=String(d.get('order')).trim(),delivery=String(d.get('delivery'));const id=[order,code,delivery].join('|');if(rows.some(x=>x.id===id)){alert('Esse pedido e item já estão cadastrados.');return}rows.push({id,code,order,delivery,description:String(d.get('description')),quantity:num(d.get('quantity')),unit:String(d.get('unit')),supplier:String(d.get('supplier')),contact:String(d.get('contact')),status:'Pendente',category:classify(String(d.get('description')),'other'),stock:null,safety:null,consumption:null,lead:null,delivered:0});try{await save();render()}catch(err){rows.pop();alert(err.message)}};
 for(const [attr,action] of [['data-receive','receive'],['data-cancel','cancel'],['data-partial','partial']])root.querySelectorAll('['+attr+']').forEach(btn=>btn.onclick=async()=>{const x=rows.find(x=>x.id===btn.getAttribute(attr));if(!x)return;const old={status:x.status,delivered:x.delivered};if(action==='receive'){x.delivered=x.quantity;x.status='Recebido'}else if(action==='cancel'){if(!confirm('Cancelar este pedido?'))return;x.status='Cancelado'}else{const value=prompt('Quantidade total já entregue (até '+x.quantity+'):',String(num(x.delivered)));if(value===null)return;const amount=num(value);if(amount<0||amount>x.quantity){alert('Quantidade inválida.');return}x.delivered=amount;x.status=amount>=x.quantity?'Recebido':'Pendente'}try{await save();render()}catch(e){Object.assign(x,old);alert(e.message)}});
 const report=()=>rows.filter(x=>(!root.dataset.indSupplier||String(x.supplier||'').toLowerCase().includes(root.dataset.indSupplier.toLowerCase()))&&(!root.dataset.indStatus||st(x)===root.dataset.indStatus)&&(!root.dataset.from||x.delivery>=root.dataset.from)&&(!root.dataset.to||x.delivery<=root.dataset.to));
 const excel=root.querySelector('[data-ind-excel]');if(excel)excel.onclick=()=>{const data=[['Código','Produto','Pedido','Fornecedor','Contato','Status','Entrega','Quantidade','Entregue','Saldo','UN'],...report().map(x=>[x.code,x.description,x.order,x.supplier||'',x.contact||'',st(x),br(x.delivery),x.quantity,num(x.delivered),Math.max(0,x.quantity-num(x.delivered)),x.unit])];const csv='\uFEFF'+data.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='prazos-insumos-epis.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
 const print=root.querySelector('[data-ind-print]');if(print)print.onclick=()=>{const html='<h2>Relatório de prazos - Insumos e EPIs</h2><table border="1" cellspacing="0" cellpadding="6"><tr><th>Código</th><th>Produto</th><th>Pedido</th><th>Fornecedor</th><th>Entrega</th><th>Status</th></tr>'+report().map(x=>'<tr>'+[x.code,x.description,x.order,x.supplier||'',br(x.delivery),st(x)].map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</table>';const w=window.open('','_blank');if(!w){alert('Permita pop-ups para imprimir.');return}w.document.write('<!doctype html><html><head><title>Relatório</title></head><body>'+html+'</body></html>');w.document.close();w.print()};
}

function render(){if(!root)return;syncIndirectNav();const f=filtered(),late=rows.filter(x=>status(x)==='Atrasado').length,upcoming=rows.filter(x=>x.status!=='Recebido'&&x.delivery>=today()).length;
const mrpSuppliers=[...new Set(rows.map(x=>x.supplier).filter(Boolean))].sort();
const mrpQuery=root.dataset.mrpQuery||'',mrpSupplier=root.dataset.mrpSupplier||'',mrpDisplay=root.dataset.mrpDisplay||'all';
const mrpCandidates=tab==='MRP'?f.filter(x=>(!mrpSupplier||x.supplier===mrpSupplier)&&(!mrpQuery||[x.code,x.description,x.order].join(' ').toLowerCase().includes(mrpQuery.toLowerCase()))&&(mrpDisplay==='all'||(mrpDisplay==='review'&&(x.stock==null||x.safety==null))||(mrpDisplay==='late'&&status(x)==='Atrasado')||(mrpDisplay==='pending'&&x.status!=='Recebido'&&x.status!=='Cancelado'))):f;
const items=[...new Map(mrpCandidates.map(x=>[x.code,x])).values()];if(!items.some(x=>x.code===selectedCode))selectedCode=items[0]?.code||'';
const chosen=f.filter(x=>x.code===selectedCode),item=chosen[0],stockStatus=x=>x.stock==null||x.safety==null?'Revisar dados':x.consumption==null||x.consumption===0?'Sem consumo':x.stock<x.safety?'Crítico':x.lead!=null&&x.stock<x.safety+x.consumption/30*x.lead?'Atenção':'Ok';
const stockSuppliers=[...new Set(rows.map(x=>x.supplier).filter(Boolean))].sort();
const stockSupplier=root.dataset.stockSupplier||'',stockRupture=root.dataset.stockRupture||'',stockVariation=root.dataset.stockVariation||'';
const rupture=x=>x.stock==null||x.safety==null?'Sem dados':x.stock<=0?'Ruptura':x.stock<x.safety?'Risco de ruptura':'Sem ruptura';
const stockItems=items.filter(x=>(!root.dataset.stockStatus||stockStatus(x)===root.dataset.stockStatus)&&(!stockSupplier||x.supplier===stockSupplier)&&(!stockRupture||rupture(x)===stockRupture)&&(!stockVariation||(stockVariation==='unknown'&&(x.previousStock==null||x.stock==null))||(stockVariation==='up'&&x.previousStock!=null&&x.stock>x.previousStock)||(stockVariation==='down'&&x.previousStock!=null&&x.stock<x.previousStock)||(stockVariation==='same'&&x.previousStock!=null&&x.stock===x.previousStock)));
const profile=()=>item?'<div class="ind-detail-title"><h2>'+esc(item.description)+'</h2><small>'+esc(item.code)+' · '+esc(item.unit)+'</small></div><div class="ind-detail-grid"><section class="panel"><h3>Perfil do item</h3>'+table(['Tipo','Referência','Data compra','Data entrega','Quantidade'],chosen.map(x=>'<tr><td>'+esc(x.type||'OCP')+'</td><td>'+esc(x.order)+'</td><td>'+br(x.purchase)+'</td><td>'+br(x.delivery)+'</td><td>'+esc(x.quantity)+' '+esc(x.unit)+'</td></tr>'))+'</section><section class="panel"><h3>Parâmetros de reposição</h3><div class="ind-params">'+[['stock','Saldo físico'],['safety','Estoque segurança'],['consumption','Consumo médio mensal'],['lead','Tempo de reposição (dias)']].map(([k,label])=>'<label>'+label+'<input type="number" min="0" step="any" data-value-id="'+esc(item.id)+'" data-field="'+k+'" value="'+(item[k]??'')+'" placeholder="Não informado"></label>').join('')+'</div></section><section class="panel"><h3>Análise de compra</h3><div class="ind-metric">'+esc(stockStatus(item))+'</div><p>'+(item.stock==null||item.safety==null?'Informe saldo físico e estoque de segurança para analisar a necessidade.':item.stock<item.safety?'Saldo abaixo do estoque de segurança. Verifique a reposição.':'Saldo acima do estoque de segurança.')+'</p><small>Pedidos pendentes: '+chosen.filter(x=>x.status!=='Recebido'&&x.status!=='Cancelado').reduce((a,x)=>a+x.quantity,0)+' '+esc(item.unit)+'</small></section></div>':'<p class="empty-state">Importe os arquivos CSV para iniciar a análise.</p>';
root.innerHTML=`
${tab==='MRP'?'<div class="ind-mrp-filters"><label>Fornecedor preferencial<select data-mrp-supplier><option value="">Todos os fornecedores</option>'+mrpSuppliers.map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join('')+'</select></label><label>Exibir<select data-mrp-display><option value="all">Todos os itens do relatório</option><option value="review">Revisar dados</option><option value="late">Pedidos atrasados</option><option value="pending">Pedidos pendentes</option></select></label><label>Material selecionado<input data-mrp-query type="search" placeholder="Código ou nome do material" value="'+esc(mrpQuery)+'"></label><button type="button" data-mrp-clear>Limpar material</button><span class="ind-mrp-count">'+items.length+' de '+new Set(f.map(x=>x.code)).size+' itens</span></div><div class="section-title"><h2>Itens do relatório MRP</h2><span>Selecione um material para analisar</span></div><div class="material-grid ind-material-grid">'+items.map(x=>'<button class="material '+(selectedCode===x.code?'active':'')+'" data-select-code="'+esc(x.code)+'"><span><small>'+esc(x.code)+' · '+esc(x.unit)+'</small><strong>'+esc(x.description)+'</strong></span><span class="material-tag">'+esc(stockStatus(x))+'</span></button>').join('')+'</div>'+profile():tab==='Estoque'?'<div class="ind-stock-toolbar"><label>Buscar produto<input data-stock-search placeholder="Código ou nome do material" value="'+esc(search)+'"></label><label>Fornecedor preferencial<select data-stock-supplier><option value="">Todos os fornecedores</option>'+stockSuppliers.map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join('')+'</select></label><label>Status de cobertura<select data-stock-status><option value="">Todos</option><option>Ok</option><option>Atenção</option><option>Crítico</option><option>Sem consumo</option><option>Revisar dados</option></select></label><label>Variação de estoque<select data-stock-variation><option value="">Todas</option><option value="up">Aumentou</option><option value="down">Diminuiu</option><option value="same">Sem alteração</option><option value="unknown">Sem histórico</option></select></label><label>Status ruptura<select data-stock-rupture><option value="">Todos</option><option>Sem ruptura</option><option>Risco de ruptura</option><option>Ruptura</option><option>Sem dados</option></select></label></div><div class="ind-stock-layout"><section class="panel"><h3>Posição dos materiais <small>'+stockItems.length+' materiais</small></h3>'+table(['Código / produto','UM','Saldo total','Estoque segurança','Cobertura (dias)','Status'],stockItems.map(x=>'<tr class="'+(selectedCode===x.code?'selected-row':'')+'"><td><button class="row-select" data-select-code="'+esc(x.code)+'"><small>'+esc(x.code)+'</small>'+esc(x.description)+'</button></td><td>'+esc(x.unit)+'</td><td>'+(x.stock??'—')+'</td><td>'+(x.safety??'—')+'</td><td>'+(x.stock!=null&&x.consumption>0?(x.stock/x.consumption*30).toFixed(1):'—')+'</td><td>'+esc(stockStatus(x))+'</td></tr>'))+'</section><aside><section class="panel"><h3>Status de cobertura</h3>'+['Ok','Atenção','Crítico','Sem consumo','Revisar dados'].map(st=>'<div class="status-bar"><span>'+st+'</span><div><i class="'+(st==='Ok'?'ok':st==='Crítico'?'critical':'attention')+'" style="width:'+(items.length?items.filter(x=>stockStatus(x)===st).length/items.length*100:0)+'%"></i></div><strong>'+items.filter(x=>stockStatus(x)===st).length+'</strong></div>').join('')+'</section><section class="panel"><h3>Perfil · '+esc(selectedCode)+'</h3>'+profile()+'</section></aside></div>':tab==='Prazos'?deadlineView():'<section class="panel import-panel"><h3>Atualizar dados do sistema</h3><p>Selecione os relatórios de insumos e EPIs. Confira os arquivos antes de importar. Os dados são mantidos separados das matérias-primas.</p><form id="ind-import-form"><label>Necessidades de compra (CSV)<input id="ind-import-csv" type="file" accept=".csv,text/csv" multiple required></label><label>Perfil dos itens (PDF)<input id="ind-import-profile" type="file" accept=".pdf" multiple></label><label>Saldo dos almoxarifados (PDF)<input id="ind-import-stock" type="file" accept=".pdf" multiple></label><button type="submit" id="ind-import-check">Conferir arquivos</button></form><div id="ind-import-result" role="status" aria-live="polite"></div><button id="ind-import-save" hidden type="button">Salvar lote no histórico</button><p>Os PDFs RPLA0300 e REST0331 são conferidos antes de salvar. Os pedidos não são somados ao saldo físico.</p></section><section class="panel import-panel"><h3>Histórico de lotes importados</h3><div id="ind-import-history">Os lotes serão registrados após a importação.</div></section>'}
<p class="method-note">As quantidades dos pedidos não são saldos físicos. Os indicadores de cobertura só são calculados quando saldo e consumo forem informados.</p><p data-feedback role="status"></p>`;
if(tab==='Prazos')wireDeadlines();
if(tab==='MRP'){
 const supplier=root.querySelector('[data-mrp-supplier]'),display=root.querySelector('[data-mrp-display]'),query=root.querySelector('[data-mrp-query]'),clear=root.querySelector('[data-mrp-clear]');
 supplier.value=mrpSupplier;display.value=mrpDisplay;
 supplier.onchange=()=>{root.dataset.mrpSupplier=supplier.value;render()};
 display.onchange=()=>{root.dataset.mrpDisplay=display.value;render()};
 query.oninput=()=>{const pos=query.selectionStart;root.dataset.mrpQuery=query.value;render();const el=root.querySelector('[data-mrp-query]');el.focus();el.setSelectionRange(pos,pos)};
 clear.onclick=()=>{root.dataset.mrpQuery='';selectedCode='';render()};
}
const stockInput=root.querySelector('[data-stock-search]');if(stockInput)stockInput.onchange=e=>{search=e.target.value;render()};
const stockStatusFilter=root.querySelector('[data-stock-status]');if(stockStatusFilter){stockStatusFilter.value=root.dataset.stockStatus||'';stockStatusFilter.onchange=e=>{root.dataset.stockStatus=e.target.value;render()};}
for(const [selector,key] of [['[data-stock-supplier]','stockSupplier'],['[data-stock-variation]','stockVariation'],['[data-stock-rupture]','stockRupture']]){const el=root.querySelector(selector);if(el){el.value=root.dataset[key]||'';el.onchange=()=>{root.dataset[key]=el.value;render()}}}
root.querySelectorAll('[data-select-code]').forEach(b=>b.onclick=()=>{selectedCode=b.dataset.selectCode;render()});

const importForm=root.querySelector('#ind-import-form');
if(importForm){const check=root.querySelector('#ind-import-check'),result=root.querySelector('#ind-import-result'),commit=root.querySelector('#ind-import-save');let pending=null;const hist=()=>{const el=root.querySelector('#ind-import-history');el.innerHTML=history.map(x=>'<p>'+esc(x.date)+' · '+esc(x.count)+' necessidades · '+esc(x.files.join(', '))+'</p>').join('')||'Nenhum lote importado nesta sessão.'};hist();importForm.onchange=()=>{pending=null;commit.hidden=true;result.textContent='Arquivos alterados. Confira novamente antes de salvar.'};const readPdf=async(file,kind)=>{const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const r=await fetch('/api/indirect-materials/parse-pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,content:btoa(binary)})});const j=await r.json();if(!r.ok)throw Error(file.name+': '+(j.error||'Falha ao processar PDF'));return j};
importForm.onsubmit=async e=>{e.preventDefault();commit.hidden=true;pending=null;check.disabled=true;result.textContent='Lendo e validando arquivos...';try{
 const files=[...root.querySelector('#ind-import-csv').files],profiles=[...root.querySelector('#ind-import-profile').files],stocks=[...root.querySelector('#ind-import-stock').files];
 if(!files.length)throw Error('Selecione os CSVs de necessidades.');
 if(!profiles.length||!stocks.length)throw Error('Selecione os PDFs de perfil e de saldo para uma importação completa.');
 let batch=[],parsed=[],dates=new Set();
 for(const file of files){const buf=await file.arrayBuffer();let content=new TextDecoder('utf-8').decode(buf);if(content.includes('�'))content=new TextDecoder('windows-1252').decode(buf);batch.push(...parseCSV(content,/epi|uniform/i.test(file.name)?'epis':'other'))}
 for(const file of profiles)parsed.push({file:file.name,...await readPdf(file,'profile')});
 for(const file of stocks)parsed.push({file:file.name,...await readPdf(file,'stock')});
 for(const p of parsed)if(p.date)dates.add(p.date);
 if(dates.size>1)throw Error('Os PDFs possuem datas de relatório diferentes. Selecione relatórios do mesmo dia.');
 const byCode=new Map();
 for(const p of parsed){for(const x of p.items){const old=byCode.get(x.code)||{code:x.code};byCode.set(x.code,{...old,...x})}}
 const updated=batch.map(x=>({...x,...(byCode.get(x.code)||{}),id:x.id,code:x.code,order:x.order,quantity:x.quantity,delivery:x.delivery,description:x.description,category:x.category}));
 const notMatched=[...new Set(batch.map(x=>x.code))].filter(code=>!byCode.has(code));
 pending={batch:updated,details:byCode,files:[...files,...profiles,...stocks].map(x=>x.name),date:[...dates][0]||new Date().toISOString().slice(0,10)};
 result.textContent=batch.length+' pedidos em '+files.length+' CSV(s); '+profiles.length+' perfil(is), '+stocks.length+' saldo(s); '+byCode.size+' materiais lidos dos PDFs. '+(notMatched.length?'Sem correspondência para: '+notMatched.join(', ')+'. ':'')+'Clique em Salvar lote para confirmar.';
 commit.hidden=false;
 }catch(err){result.textContent='Erro: '+err.message;commit.hidden=true}finally{check.disabled=false}};
commit.onclick=async()=>{if(!pending)return;commit.disabled=true;try{
 const map=new Map(rows.map(x=>[x.id,x]));
 for(const item of pending.batch){const old=map.get(item.id)||{};map.set(item.id,{...old,...item,status:old.status||item.status,delivered:old.delivered||0})}
 for(const [code,details] of pending.details){if(!/^NE\d{4}$/.test(code))continue;if(![...map.values()].some(x=>x.code===code)){const id='PROFILE|'+code;map.set(id,{id,code,order:'',description:details.description,unit:details.unit,quantity:0,delivery:'',status:'Pendente',category:classify(details.description,/CAMISETA|CALCA|BOTINA|RESPIRADOR/i.test(details.description)?'epis':'other'),...details})}else for(const item of map.values())if(item.code===code)Object.assign(item,details)}
 const previous=rows;rows=[...map.values()];const h={date:br(pending.date),count:pending.batch.length,files:pending.files,profiles:[...pending.details].length};
 history=[h,...history];try{await save()}catch(e){rows=previous;history.shift();throw e}
 pending=null;render();const output=root.querySelector('#ind-import-result');if(output)output.textContent='Lote importado com sucesso: CSVs e PDFs processados.';
 }catch(err){result.textContent='Falha ao salvar: '+err.message}finally{commit.disabled=false}};
}
root.querySelectorAll('[data-import]').forEach(upload=>upload.onchange=async e=>{try{let added=0;for(const file of e.target.files){const buf=await file.arrayBuffer();let text=new TextDecoder('utf-8',{fatal:false}).decode(buf);if(text.includes('�'))text=new TextDecoder('windows-1252').decode(buf);const group=/epi|uniform/i.test(file.name)?'epis':'other';const incoming=parseCSV(text,group),map=new Map(rows.map(x=>[x.id,x]));for(const item of incoming){map.set(item.id,{...item,...(map.get(item.id)||{}),description:item.description,quantity:item.quantity,delivery:item.delivery})}rows=[...map.values()];added+=incoming.length}await save();render();root.querySelector('[data-feedback]').textContent=added+' registros processados e salvos.'}catch(err){root.querySelector('[data-feedback]').textContent='Erro na importação: '+err.message}});
root.querySelectorAll('[data-status-id]').forEach(el=>el.onchange=async()=>{const x=rows.find(x=>x.id===el.dataset.statusId);if(!x)return;const old=x.status;x.status=el.value;try{await save();render()}catch(e){x.status=old;alert(e.message)}});
root.querySelectorAll('[data-value-id]').forEach(el=>el.onchange=async()=>{const x=rows.find(x=>x.id===el.dataset.valueId),k=el.dataset.field;if(!x)return;const old=x[k];x[k]=el.value===''?null:Math.max(0,num(el.value));try{await save();render()}catch(e){x[k]=old;alert(e.message)}});

const exportButton=root.querySelector('[data-export]');if(exportButton)exportButton.onclick=()=>{const heads=['Categoria','Código','Descrição','Pedido','Quantidade','UM','Compra','Entrega','Situação','Estoque','Segurança','Consumo','Reposição'];const data=filtered().map(x=>[x.category,x.code,x.description,x.order,x.quantity,x.unit,br(x.purchase),br(x.delivery),status(x),x.stock??'',x.safety??'',x.consumption??'',x.lead??'']);const csv='\uFEFF'+[heads,...data].map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='materiais-indiretos.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
}
function table(heads,rs){return '<div class="table-scroll"><table><thead><tr>'+heads.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+(rs.length?rs.join(''):'<tr><td colspan="'+heads.length+'">Nenhum item. Importe os CSVs do Focco3i para começar.</td></tr>')+'</tbody></table></div>'}
syncIndirectNav();load();window.addEventListener('hashchange',()=>{syncIndirectNav();if(Object.hasOwn(routeTabs,location.hash.slice(1)))load()});
